) AS catalog(itemName, description) ON item.itemName = catalog.itemName
SET item.description = catalog.description
WHERE BINARY item.description <> BINARY catalog.description;

SELECT ROW_COUNT() AS updated_items;
SELECT COUNT(*) AS total_items,
       SUM(description LIKE '%Hướng dẫn sử dụng%Bảo quản%Lưu ý%') AS items_with_detailed_description
FROM tblItem6;
